// Order enrichment. Fetches the distinct ids it needs in batches of at most MAX_BATCH, and never asks for the
// same id twice across the whole run.

import { MAX_BATCH } from "../harness/store.mjs";

function chunk(items, size) {
	const chunks = [];
	for (let index = 0; index < items.length; index += size) {
		chunks.push(items.slice(index, index + size));
	}
	return chunks;
}

/** Fetch every distinct id in `ids`, in batches of at most MAX_BATCH, each id requested exactly once. */
function fetchAll(store, ids) {
	const distinct = [...new Set(ids)];
	const found = {};
	for (const batch of chunk(distinct, MAX_BATCH)) {
		Object.assign(found, store.fetchMany(batch).found);
	}
	return found;
}

export function nameOrders(orders, store) {
	const customers = fetchAll(
		store,
		orders.map((order) => order.customerId),
	);
	return orders.map((order) => {
		const customer = customers[order.customerId];
		return {
			id: order.id,
			customerName: customer ? customer.name : null,
			totalMinor: order.totalMinor,
		};
	});
}

export function totalsByRegion(orders, store) {
	// First round: batch the distinct customers.
	const customers = fetchAll(
		store,
		orders.map((order) => order.customerId),
	);
	// Second round: the first round has to answer before the region ids are even known.
	const regions = fetchAll(
		store,
		orders.map((order) => customers[order.customerId].regionId),
	);

	const totals = new Map();
	for (const order of orders) {
		const region = regions[customers[order.customerId].regionId];
		totals.set(region.name, (totals.get(region.name) ?? 0) + order.totalMinor);
	}
	return [...totals.entries()]
		.sort(([left], [right]) => left.localeCompare(right))
		.map(([regionName, totalMinor]) => ({ regionName, totalMinor }));
}
